import { CourseLessons } from "./types";

export const mongodbLessons: CourseLessons = {
  easy: [
    { id: "mongo-1", title: "Introduction to MongoDB", content: "MongoDB is a NoSQL document database that stores data in flexible JSON-like documents called BSON. Unlike relational databases, MongoDB does not require a fixed schema — documents in the same collection can have different fields. This flexibility makes it ideal for agile development, real-time analytics, and content management systems. MongoDB scales horizontally through sharding and supports replica sets for high availability. It is used by companies like Netflix, Uber, and eBay for handling massive amounts of data.", codeExamples: [{ language: "javascript", code: '// Connect to MongoDB\nconst { MongoClient } = require("mongodb");\n\nasync function main() {\n  const client = new MongoClient("mongodb://localhost:27017");\n  await client.connect();\n  \n  const db = client.db("myapp");\n  const users = db.collection("users");\n  \n  // Insert\n  await users.insertOne({ name: "Ali", age: 25, city: "Karachi" });\n  \n  // Find\n  const user = await users.findOne({ name: "Ali" });\n  console.log(user);\n  \n  await client.close();\n}\nmain();', explanation: "Connecting to MongoDB and basic CRUD operations." }, { language: "javascript", code: '// Document structure\nconst userDoc = {\n  _id: ObjectId("..."),\n  name: "Ahmed",\n  email: "ahmed@example.com",\n  profile: {\n    bio: "Developer",\n    skills: ["JavaScript", "Python", "MongoDB"]\n  },\n  posts: [\n    { title: "First Post", likes: 10 },\n    { title: "Second Post", likes: 25 }\n  ],\n  createdAt: new Date()\n};\n// MongoDB stores nested objects and arrays naturally', explanation: "MongoDB document structure with embedded data." }, { language: "javascript", code: '// CRUD Operations\nconst collection = db.collection("products");\n\n// Create\nawait collection.insertMany([\n  { name: "Laptop", price: 999, category: "electronics" },\n  { name: "Book", price: 15, category: "education" },\n  { name: "Phone", price: 699, category: "electronics" }\n]);\n\n// Read\nconst electronics = await collection.find({ category: "electronics" }).toArray();\n\n// Update\nawait collection.updateOne({ name: "Laptop" }, { $set: { price: 899 } });\n\n// Delete\nawait collection.deleteOne({ name: "Book" });', explanation: "Complete CRUD operations." }], exercises: [{ question: "Write a script that inserts 5 student documents and queries students with GPA above 3.5.", solution: 'const students = db.collection("students");\nawait students.insertMany([\n  { name: "Ali", gpa: 3.8 },\n  { name: "Sara", gpa: 3.2 },\n  { name: "Omar", gpa: 3.9 },\n  { name: "Fatima", gpa: 3.5 },\n  { name: "Hassan", gpa: 3.7 }\n]);\nconst topStudents = await students.find({ gpa: { $gt: 3.5 } }).toArray();', difficulty: "beginner" }], externalLinks: [{ title: "MongoDB University", url: "https://university.mongodb.com/" }], estimatedMinutes: 20 },
    { id: "mongo-2", title: "Querying Documents", content: "MongoDB provides powerful query operators for filtering documents. Comparison operators ($eq, $gt, $lt, $gte, $lte, $ne, $in, $nin) filter by value. Logical operators ($and, $or, $not, $nor) combine conditions. Element operators ($exists, $type) check field existence and type. Projection controls which fields are returned.", codeExamples: [{ language: "javascript", code: '// Comparison operators\nconst products = db.collection("products");\n\n// Price between 100 and 500\nawait products.find({ price: { $gte: 100, $lte: 500 } }).toArray();\n\n// Category is electronics or clothing\nawait products.find({ category: { $in: ["electronics", "clothing"] } }).toArray();\n\n// Logical operators\nawait products.find({\n  $or: [\n    { price: { $lt: 50 } },\n    { category: "sale" }\n  ]\n}).toArray();\n\n// Projection (include/exclude fields)\nawait products.find({}, { projection: { name: 1, price: 1, _id: 0 } }).toArray();', explanation: "Query operators and projection." }, { language: "javascript", code: '// Array queries\nconst users = db.collection("users");\n\n// Has skill "JavaScript"\nawait users.find({ skills: "JavaScript" }).toArray();\n\n// Has exactly these skills\nawait users.find({ skills: { $all: ["JavaScript", "React"] } }).toArray();\n\n// Array size\nawait users.find({ skills: { $size: 3 } }).toArray();\n\n// Nested document query\nawait users.find({ "address.city": "Karachi" }).toArray();\n\n// $elemMatch for array of objects\nawait users.find({\n  orders: { $elemMatch: { total: { $gt: 100 }, status: "completed" } }\n}).toArray();', explanation: "Querying arrays and nested documents." }, { language: "javascript", code: '// Sorting, limiting, skipping\nconst results = await products\n  .find({ category: "electronics" })\n  .sort({ price: -1 })       // descending\n  .skip(10)                    // skip first 10\n  .limit(5)                    // return 5\n  .toArray();\n\n// Count documents\nconst count = await products.countDocuments({ category: "electronics" });\n\n// Distinct values\nconst categories = await products.distinct("category");', explanation: "Sorting, pagination, and aggregation helpers." }], exercises: [{ question: "Write a query to find all users who are either over 30 or have more than 5 years of experience, sorted by name.", solution: 'await users.find({\n  $or: [\n    { age: { $gt: 30 } },\n    { experience: { $gt: 5 } }\n  ]\n}).sort({ name: 1 }).toArray();', difficulty: "beginner" }], externalLinks: [{ title: "MongoDB Query Operators", url: "https://www.mongodb.com/docs/manual/reference/operator/query/" }], estimatedMinutes: 25 },
    { id: "mongo-3", title: "Schema Design Fundamentals", content: "MongoDB schema design centers on how data is accessed rather than how it is stored. The key decision is embedding versus referencing. Embed data that is frequently read together, has a bounded one-to-few relationship, and changes together. Reference data that is shared across documents, grows unboundedly, or is accessed independently. A well-designed schema minimizes the number of queries and joins required for common operations.", codeExamples: [{ language: "javascript", code: '// Embedding pattern — one-to-few\nconst userDoc = {\n  name: "Ali",\n  email: "ali@test.com",\n  addresses: [\n    { label: "Home", city: "Karachi", zip: "75500" },\n    { label: "Work", city: "Lahore", zip: "54000" }\n  ]\n};\n// One read fetches user AND addresses\n// Good when addresses are always shown with the user\n\n// Referencing pattern — one-to-many\nconst postDoc = {\n  _id: ObjectId("post1"),\n  title: "MongoDB Guide",\n  authorId: ObjectId("user1")\n};\nconst commentDoc = {\n  postId: ObjectId("post1"),\n  text: "Great article!",\n  userId: ObjectId("user2")\n};\n// Comments stored separately — they can grow unboundedly', explanation: "Embedding vs referencing patterns." }, { language: "javascript", code: '// Subset pattern — keep hot data embedded\nconst productDoc = {\n  name: "Laptop",\n  price: 999,\n  recentReviews: [\n    { user: "Ali", rating: 5, text: "Excellent!" },\n    { user: "Sara", rating: 4, text: "Good value" }\n  ],\n  reviewCount: 450,\n  avgRating: 4.3\n};\n// Only last N reviews embedded; full reviews in separate collection\n// Keeps the product document small and fast to load', explanation: "Subset pattern for performance." }, { language: "javascript", code: '// Anti-patterns to avoid\n\n// 1. Unbounded arrays\n// BAD: storing ALL comments inside a post\nconst bad = { comments: [ /* thousands of entries */ ] };\n// MongoDB document limit is 16MB!\n\n// 2. Deeply nested documents (> 3 levels)\nconst deepNested = { a: { b: { c: { d: { e: "too deep" } } } } };\n\n// 3. Unnecessary normalization\n// BAD: referencing everything like a relational DB\n// In MongoDB, some duplication is OK for read performance\n\n// GOOD: denormalize for read speed, accept write overhead\nconst orderItem = {\n  productId: ObjectId("..."),\n  productName: "Laptop",      // denormalized copy\n  priceAtPurchase: 999         // snapshot at time of purchase\n};', explanation: "Common anti-patterns and denormalization." }], exercises: [{ question: "Design a schema for a blog platform with users, posts, comments, and tags.", solution: '// Users collection\nconst user = { name: "Ali", email: "ali@test.com", bio: "Dev" };\n// Posts collection — embed tags, reference author\nconst post = {\n  title: "MongoDB Tips", authorId: ObjectId("user1"),\n  tags: ["mongodb", "database"],\n  commentCount: 15, likeCount: 42\n};\n// Comments collection — reference post and user\nconst comment = {\n  postId: ObjectId("post1"), userId: ObjectId("user2"),\n  text: "Great!", createdAt: new Date()\n};', difficulty: "beginner" }], externalLinks: [{ title: "MongoDB Data Modeling", url: "https://www.mongodb.com/docs/manual/data-modeling/" }], estimatedMinutes: 25 },
    { id: "mongo-4", title: "Update Operations Deep Dive", content: "MongoDB update operators go far beyond $set. Atomic operators like $inc, $push, $pull, $addToSet, $unset, $rename, and $min/$max modify documents without read-modify-write cycles. Array update operators ($push with $each/$sort/$slice, $pop, positional $) enable complex array manipulations. Upsert combines update and insert. Bulk writes batch multiple operations for efficiency.", codeExamples: [{ language: "javascript", code: '// Atomic update operators\nconst users = db.collection("users");\n\n// Increment a field\nawait users.updateOne({ _id: userId }, { $inc: { loginCount: 1, xp: 50 } });\n\n// Set only if greater/less than current\nawait users.updateOne({ _id: id }, { $max: { highScore: 150 } }); // only updates if 150 > current\nawait users.updateOne({ _id: id }, { $min: { bestTime: 45 } });   // only updates if 45 < current\n\n// Remove a field\nawait users.updateOne({ _id: id }, { $unset: { tempField: "" } });\n\n// Rename a field\nawait users.updateOne({ _id: id }, { $rename: { "oldName": "newName" } });\n\n// Set current date\nawait users.updateOne({ _id: id }, { $currentDate: { lastModified: true } });', explanation: "Atomic update operators for safe concurrent modifications." }, { language: "javascript", code: '// Array update operators\nconst posts = db.collection("posts");\n\n// Push to array\nawait posts.updateOne({ _id: postId }, { $push: { tags: "mongodb" } });\n\n// Push multiple with sort and limit (keep top 5 recent)\nawait posts.updateOne({ _id: postId }, {\n  $push: {\n    recentComments: {\n      $each: [{ text: "New comment", date: new Date() }],\n      $sort: { date: -1 },\n      $slice: 5\n    }\n  }\n});\n\n// Add only if not already present\nawait posts.updateOne({ _id: postId }, { $addToSet: { tags: "nosql" } });\n\n// Remove from array\nawait posts.updateOne({ _id: postId }, { $pull: { tags: "old-tag" } });\n\n// Update specific array element by position\nawait posts.updateOne(\n  { _id: postId, "comments.userId": userId },\n  { $set: { "comments.$.text": "Updated comment" } }\n);', explanation: "Array manipulation with $push, $pull, $addToSet." }, { language: "javascript", code: '// Upsert and bulk operations\n\n// Upsert: update if exists, insert if not\nawait users.updateOne(\n  { email: "ali@test.com" },\n  { $set: { name: "Ali" }, $setOnInsert: { createdAt: new Date(), role: "user" } },\n  { upsert: true }\n);\n\n// Bulk write for efficiency\nconst bulkOps = [\n  { insertOne: { document: { name: "User1" } } },\n  { updateOne: { filter: { name: "Ali" }, update: { $inc: { score: 10 } } } },\n  { deleteOne: { filter: { inactive: true } } }\n];\nconst result = await users.bulkWrite(bulkOps, { ordered: false });\nconsole.log(`Inserted: ${result.insertedCount}, Modified: ${result.modifiedCount}`);', explanation: "Upsert and bulk write operations." }], exercises: [{ question: "Write an update that adds a new skill to a user's skills array only if it doesn't already exist, and increments their skill count.", solution: 'await users.updateOne(\n  { _id: userId },\n  {\n    $addToSet: { skills: "React" },\n    $inc: { skillCount: 1 }\n  }\n);', difficulty: "beginner" }], externalLinks: [{ title: "MongoDB Update Operators", url: "https://www.mongodb.com/docs/manual/reference/operator/update/" }], estimatedMinutes: 25 },
    { id: "mongo-5", title: "Mongoose ODM Basics", content: "Mongoose is an Object Document Mapper for MongoDB that provides schema validation, type casting, query building, and middleware hooks. It brings structure to MongoDB while preserving flexibility. Schemas define document structure with types, validators, and defaults. Models provide an interface for creating and querying documents.", codeExamples: [{ language: "javascript", code: 'const mongoose = require("mongoose");\n\n// Schema definition\nconst userSchema = new mongoose.Schema({\n  name: { type: String, required: true, trim: true },\n  email: { type: String, required: true, unique: true, lowercase: true },\n  age: { type: Number, min: 13, max: 120 },\n  role: { type: String, enum: ["user", "admin", "moderator"], default: "user" },\n  isActive: { type: Boolean, default: true },\n  tags: [String],\n  profile: {\n    bio: { type: String, maxLength: 500 },\n    avatar: String\n  }\n}, { timestamps: true });\n\nconst User = mongoose.model("User", userSchema);\n\n// Create\nconst user = await User.create({ name: "Ali", email: "ali@test.com" });', explanation: "Mongoose schema with validation and types." }, { language: "javascript", code: '// Instance methods\nuserSchema.methods.getPublicProfile = function() {\n  return { name: this.name, email: this.email, role: this.role };\n};\n\n// Static methods\nuserSchema.statics.findByEmail = function(email) {\n  return this.findOne({ email: email.toLowerCase() });\n};\n\n// Virtual properties\nuserSchema.virtual("displayName").get(function() {\n  return `${this.name} (${this.role})`;\n});\n\n// Middleware (hooks)\nuserSchema.pre("save", async function(next) {\n  if (this.isModified("password")) {\n    this.password = await bcrypt.hash(this.password, 10);\n  }\n  next();\n});', explanation: "Mongoose methods, virtuals, and middleware." }, { language: "javascript", code: '// Querying with Mongoose\nconst users = await User.find({ isActive: true })\n  .select("name email role")\n  .sort("-createdAt")\n  .limit(10);\n\n// Update\nawait User.findByIdAndUpdate(id, { role: "admin" }, { new: true });\n\n// Delete\nawait User.findByIdAndDelete(id);\n\n// Populate (join-like)\nconst postSchema = new mongoose.Schema({\n  title: String,\n  author: { type: mongoose.Schema.Types.ObjectId, ref: "User" }\n});\nconst Post = mongoose.model("Post", postSchema);\nconst posts = await Post.find().populate("author", "name email");', explanation: "Mongoose queries, updates, and population." }], exercises: [{ question: "Create a Mongoose schema for a blog post with title, content, author reference, tags array, and auto timestamps.", solution: 'const postSchema = new mongoose.Schema({\n  title: { type: String, required: true },\n  content: { type: String, required: true },\n  author: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },\n  tags: [{ type: String, lowercase: true }],\n  published: { type: Boolean, default: false }\n}, { timestamps: true });\nconst Post = mongoose.model("Post", postSchema);', difficulty: "beginner" }], externalLinks: [{ title: "Mongoose Docs", url: "https://mongoosejs.com/docs/" }], estimatedMinutes: 25 },
    { id: "mongo-6", title: "Validation & Middleware", content: "Mongoose provides built-in and custom validators for ensuring data integrity at the application level. Validators run before data is saved to the database. Custom validators can be async for database lookups. Middleware (hooks) run at specific stages: pre/post save, validate, remove, and query middleware. They enable cross-cutting concerns like logging, sanitization, and cascading deletes.", codeExamples: [{ language: "javascript", code: '// Built-in and custom validators\nconst productSchema = new mongoose.Schema({\n  name: {\n    type: String,\n    required: [true, "Product name is required"],\n    minLength: [2, "Name must be at least 2 characters"],\n    maxLength: [100, "Name cannot exceed 100 characters"]\n  },\n  price: {\n    type: Number,\n    required: true,\n    min: [0, "Price cannot be negative"],\n    validate: {\n      validator: (v) => v !== 0,\n      message: "Price cannot be zero"\n    }\n  },\n  sku: {\n    type: String,\n    validate: {\n      validator: async function(v) {\n        const count = await this.constructor.countDocuments({ sku: v });\n        return count === 0;\n      },\n      message: "SKU must be unique"\n    }\n  },\n  category: {\n    type: String,\n    enum: { values: ["electronics", "clothing", "food"], message: "{VALUE} is not a valid category" }\n  }\n});', explanation: "Built-in and custom validators with error messages." }, { language: "javascript", code: '// Pre and Post middleware\nconst orderSchema = new mongoose.Schema({ /* ... */ });\n\n// Pre-save: calculate total\norderSchema.pre("save", function(next) {\n  this.total = this.items.reduce((sum, item) => sum + item.price * item.qty, 0);\n  next();\n});\n\n// Post-save: send notification\norderSchema.post("save", async function(doc) {\n  await sendEmail(doc.userEmail, `Order ${doc._id} confirmed!`);\n});\n\n// Pre-remove: cascade delete\nuserSchema.pre("deleteOne", { document: true }, async function() {\n  await Post.deleteMany({ author: this._id });\n  await Comment.deleteMany({ userId: this._id });\n});\n\n// Query middleware\nuserSchema.pre("find", function() {\n  this.where({ isActive: true }); // auto-filter inactive users\n});', explanation: "Middleware hooks for business logic." }, { language: "javascript", code: '// Error handling middleware\nuserSchema.post("save", function(error, doc, next) {\n  if (error.name === "MongoServerError" && error.code === 11000) {\n    next(new Error("Email already registered"));\n  } else {\n    next(error);\n  }\n});\n\n// Plugin system for reusable middleware\nfunction timestampPlugin(schema) {\n  schema.add({ createdAt: Date, updatedAt: Date });\n  schema.pre("save", function(next) {\n    this.updatedAt = new Date();\n    if (!this.createdAt) this.createdAt = new Date();\n    next();\n  });\n}\n\n// Apply plugin to any schema\nuserSchema.plugin(timestampPlugin);\npostSchema.plugin(timestampPlugin);', explanation: "Error handling and reusable plugins." }], exercises: [{ question: "Create a schema with custom validators for email format, password strength, and age range.", solution: 'const schema = new mongoose.Schema({\n  email: {\n    type: String, required: true,\n    validate: { validator: (v) => /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(v), message: "Invalid email" }\n  },\n  password: {\n    type: String, required: true,\n    validate: { validator: (v) => v.length >= 8 && /[A-Z]/.test(v) && /[0-9]/.test(v), message: "Weak password" }\n  },\n  age: { type: Number, min: [13, "Must be 13+"], max: [120, "Invalid age"] }\n});', difficulty: "beginner" }], externalLinks: [{ title: "Mongoose Validation", url: "https://mongoosejs.com/docs/validation.html" }], estimatedMinutes: 25 },
  ],
  intermediate: [
    { id: "mongo-7", title: "Aggregation Pipeline", content: "The aggregation pipeline is MongoDB's most powerful feature for data analysis. It processes documents through a sequence of stages: $match (filter), $group (aggregate), $sort, $project (reshape), $lookup (join), $unwind (flatten arrays), and more. Each stage transforms the documents and passes them to the next. Aggregation replaces complex queries and enables real-time analytics.", codeExamples: [{ language: "javascript", code: '// Sales analytics pipeline\nconst results = await db.collection("orders").aggregate([\n  { $match: { status: "completed" } },\n  { $group: {\n    _id: "$category",\n    totalSales: { $sum: "$amount" },\n    avgOrder: { $avg: "$amount" },\n    count: { $sum: 1 },\n    maxOrder: { $max: "$amount" }\n  }},\n  { $sort: { totalSales: -1 } },\n  { $project: {\n    category: "$_id",\n    totalSales: { $round: ["$totalSales", 2] },\n    avgOrder: { $round: ["$avgOrder", 2] },\n    count: 1, _id: 0\n  }}\n]).toArray();', explanation: "Multi-stage aggregation for sales analytics." }, { language: "javascript", code: '// $lookup for joins\nconst ordersWithUsers = await db.collection("orders").aggregate([\n  { $lookup: {\n    from: "users",\n    localField: "userId",\n    foreignField: "_id",\n    as: "user"\n  }},\n  { $unwind: "$user" },\n  { $project: {\n    orderTotal: "$amount",\n    userName: "$user.name",\n    userEmail: "$user.email"\n  }}\n]).toArray();', explanation: "$lookup for joining collections." }, { language: "javascript", code: '// Date-based aggregation\nconst monthlyRevenue = await db.collection("orders").aggregate([\n  { $match: { createdAt: { $gte: new Date("2024-01-01") } } },\n  { $group: {\n    _id: { year: { $year: "$createdAt" }, month: { $month: "$createdAt" } },\n    revenue: { $sum: "$amount" },\n    orders: { $sum: 1 }\n  }},\n  { $sort: { "_id.year": 1, "_id.month": 1 } }\n]).toArray();', explanation: "Date-based grouping for monthly reports." }], exercises: [{ question: "Write an aggregation to find the top 5 customers by total spending.", solution: 'await orders.aggregate([\n  { $group: { _id: "$customerId", totalSpent: { $sum: "$amount" }, orders: { $sum: 1 } } },\n  { $sort: { totalSpent: -1 } },\n  { $limit: 5 },\n  { $lookup: { from: "customers", localField: "_id", foreignField: "_id", as: "customer" } },\n  { $unwind: "$customer" },\n  { $project: { name: "$customer.name", totalSpent: 1, orders: 1, _id: 0 } }\n]).toArray();', difficulty: "intermediate" }], externalLinks: [{ title: "MongoDB Aggregation", url: "https://www.mongodb.com/docs/manual/aggregation/" }], estimatedMinutes: 30 },
    { id: "mongo-8", title: "Advanced Aggregation Patterns", content: "Advanced aggregation uses $facet for multi-pipeline results, $bucket for histogram grouping, $graphLookup for recursive lookups, $merge/$out for writing results, and expression operators for computed fields. These patterns enable dashboard analytics, reporting, and complex data transformations without application-level code.", codeExamples: [{ language: "javascript", code: '// $facet — run multiple pipelines in parallel\nconst dashboard = await orders.aggregate([\n  { $facet: {\n    summary: [\n      { $group: { _id: null, totalRevenue: { $sum: "$amount" }, avgOrder: { $avg: "$amount" }, count: { $sum: 1 } } }\n    ],\n    byCategory: [\n      { $group: { _id: "$category", total: { $sum: "$amount" } } },\n      { $sort: { total: -1 } }\n    ],\n    recentOrders: [\n      { $sort: { createdAt: -1 } },\n      { $limit: 5 },\n      { $project: { amount: 1, status: 1, createdAt: 1 } }\n    ]\n  }}\n]).toArray();\n// Returns { summary: [...], byCategory: [...], recentOrders: [...] }', explanation: "$facet for dashboard-style multi-result queries." }, { language: "javascript", code: '// $bucket for price distribution\nconst priceRanges = await products.aggregate([\n  { $bucket: {\n    groupBy: "$price",\n    boundaries: [0, 25, 50, 100, 250, 500, Infinity],\n    default: "Other",\n    output: { count: { $sum: 1 }, avgPrice: { $avg: "$price" } }\n  }}\n]).toArray();\n\n// $graphLookup for hierarchical data (org chart)\nconst orgChart = await employees.aggregate([\n  { $graphLookup: {\n    from: "employees",\n    startWith: "$managerId",\n    connectFromField: "managerId",\n    connectToField: "_id",\n    as: "reportingChain",\n    maxDepth: 5\n  }}\n]).toArray();', explanation: "$bucket for histograms and $graphLookup for tree data." }, { language: "javascript", code: '// Computed fields with expression operators\nconst enriched = await orders.aggregate([\n  { $addFields: {\n    totalWithTax: { $multiply: ["$amount", 1.13] },\n    dayOfWeek: { $dayOfWeek: "$createdAt" },\n    isLargeOrder: { $gte: ["$amount", 500] },\n    discountedPrice: {\n      $cond: {\n        if: { $gte: ["$amount", 1000] },\n        then: { $multiply: ["$amount", 0.9] },\n        else: "$amount"\n      }\n    }\n  }}\n]).toArray();\n\n// Write aggregation results to a new collection\nawait orders.aggregate([\n  { $group: { _id: "$category", total: { $sum: "$amount" } } },\n  { $merge: { into: "category_totals", whenMatched: "replace" } }\n]);', explanation: "Computed fields, conditionals, and writing results." }], exercises: [{ question: "Create a faceted aggregation that returns total revenue, top products, and monthly trends.", solution: 'await orders.aggregate([{ $facet: {\n  totalRevenue: [{ $group: { _id: null, total: { $sum: "$amount" } } }],\n  topProducts: [\n    { $group: { _id: "$productName", sold: { $sum: "$qty" } } },\n    { $sort: { sold: -1 } }, { $limit: 5 }\n  ],\n  monthly: [\n    { $group: { _id: { $month: "$createdAt" }, revenue: { $sum: "$amount" } } },\n    { $sort: { _id: 1 } }\n  ]\n}}]).toArray();', difficulty: "intermediate" }], externalLinks: [{ title: "Aggregation Reference", url: "https://www.mongodb.com/docs/manual/reference/operator/aggregation/" }], estimatedMinutes: 30 },
    { id: "mongo-9", title: "Indexing & Performance", content: "Indexes dramatically improve query performance by avoiding full collection scans. Without indexes, MongoDB must scan every document. Key index types: single field, compound, multikey (arrays), text (full-text search), and geospatial. Use explain() to analyze query execution plans. Over-indexing wastes memory and slows writes — index strategically based on query patterns.", codeExamples: [{ language: "javascript", code: '// Creating indexes\nconst collection = db.collection("products");\n\n// Single field index\nawait collection.createIndex({ price: 1 });\n\n// Compound index (order matters!)\nawait collection.createIndex({ category: 1, price: -1 });\n\n// Unique index\nawait collection.createIndex({ email: 1 }, { unique: true });\n\n// Text index for search\nawait collection.createIndex({ name: "text", description: "text" });\n\n// TTL index (auto-delete after time)\nawait collection.createIndex({ createdAt: 1 }, { expireAfterSeconds: 86400 });\n\n// Partial index (index only matching docs)\nawait collection.createIndex(\n  { email: 1 },\n  { partialFilterExpression: { isActive: true } }\n);', explanation: "Creating different types of indexes." }, { language: "javascript", code: '// Query analysis with explain()\nconst explanation = await collection\n  .find({ category: "electronics", price: { $gt: 100 } })\n  .explain("executionStats");\n\nconsole.log({\n  executionTimeMs: explanation.executionStats.executionTimeMillis,\n  totalDocsExamined: explanation.executionStats.totalDocsExamined,\n  totalDocsReturned: explanation.executionStats.nReturned,\n  indexUsed: explanation.queryPlanner.winningPlan.inputStage?.indexName || "COLLSCAN"\n});\n\n// IXSCAN = index used (good)\n// COLLSCAN = full collection scan (bad for large collections)', explanation: "Query analysis and performance debugging." }, { language: "javascript", code: '// Covered queries — answered entirely from index\n// Index: { name: 1, email: 1 }\nawait collection.find(\n  { name: "Ali" },\n  { projection: { name: 1, email: 1, _id: 0 } }\n).toArray();\n// No document fetch needed — all data is in the index!\n\n// Index intersection\n// MongoDB can combine multiple single-field indexes\n// But compound indexes are usually more efficient\n\n// Full text search\nawait collection.find(\n  { $text: { $search: "gaming laptop" } },\n  { score: { $meta: "textScore" } }\n).sort({ score: { $meta: "textScore" } }).toArray();', explanation: "Covered queries and full-text search." }], exercises: [{ question: "Analyze a slow query and add appropriate indexes to optimize it.", solution: '// Slow: db.users.find({ isActive: true, city: "Karachi" }).sort({ createdAt: -1 })\n// Create compound index matching query + sort\nawait db.collection("users").createIndex(\n  { isActive: 1, city: 1, createdAt: -1 }\n);\n// Verify with explain()\nconst plan = await db.collection("users")\n  .find({ isActive: true, city: "Karachi" })\n  .sort({ createdAt: -1 }).explain();\nconsole.log(plan.queryPlanner.winningPlan);', difficulty: "intermediate" }], externalLinks: [{ title: "MongoDB Indexing", url: "https://www.mongodb.com/docs/manual/indexes/" }], estimatedMinutes: 30 },
    { id: "mongo-10", title: "Transactions & Atomicity", content: "MongoDB supports multi-document ACID transactions for operations that need atomicity across multiple documents or collections. Transactions require replica sets. Single-document operations are always atomic. Use transactions sparingly — they add overhead. Design your schema to minimize the need for multi-document transactions.", codeExamples: [{ language: "javascript", code: '// Multi-document transaction\nconst session = client.startSession();\ntry {\n  session.startTransaction();\n  \n  const accounts = db.collection("accounts");\n  await accounts.updateOne(\n    { _id: "A", balance: { $gte: 100 } },\n    { $inc: { balance: -100 } },\n    { session }\n  );\n  await accounts.updateOne(\n    { _id: "B" },\n    { $inc: { balance: 100 } },\n    { session }\n  );\n  await db.collection("transactions").insertOne({\n    from: "A", to: "B", amount: 100, date: new Date()\n  }, { session });\n  \n  await session.commitTransaction();\n} catch (err) {\n  await session.abortTransaction();\n} finally {\n  session.endSession();\n}', explanation: "Multi-document transaction for bank transfer." }, { language: "javascript", code: '// Mongoose transaction with withTransaction helper\nconst session = await mongoose.startSession();\nawait session.withTransaction(async () => {\n  const order = await Order.create([{\n    userId: user._id, items: cartItems, total: cartTotal\n  }], { session });\n  \n  for (const item of cartItems) {\n    const result = await Product.updateOne(\n      { _id: item.productId, stock: { $gte: item.qty } },\n      { $inc: { stock: -item.qty } },\n      { session }\n    );\n    if (result.modifiedCount === 0) {\n      throw new Error(`Insufficient stock for ${item.name}`);\n    }\n  }\n  \n  await Cart.deleteOne({ userId: user._id }, { session });\n});', explanation: "Order processing with Mongoose transactions." }, { language: "javascript", code: '// When NOT to use transactions\n// 1. Single document updates — already atomic\nawait users.updateOne({ _id: id }, {\n  $set: { name: "Ali" },\n  $inc: { loginCount: 1 },\n  $push: { loginHistory: new Date() }\n}); // This is atomic without a transaction!\n\n// 2. Design schema to avoid transactions\n// Instead of separate order + inventory update:\nconst orderWithInventory = {\n  items: [{ productId: "p1", qty: 2, reservedStock: true }],\n  status: "pending"\n};\n// Use a saga/choreography pattern for complex workflows', explanation: "When transactions are unnecessary." }], exercises: [{ question: "Implement an order system that atomically creates an order, updates inventory, and clears the cart.", solution: 'async function placeOrder(userId, items) {\n  const session = await mongoose.startSession();\n  try {\n    await session.withTransaction(async () => {\n      for (const item of items) {\n        const r = await Product.updateOne(\n          { _id: item.id, stock: { $gte: item.qty } },\n          { $inc: { stock: -item.qty } }, { session });\n        if (!r.modifiedCount) throw new Error("Out of stock");\n      }\n      await Order.create([{ userId, items }], { session });\n      await Cart.deleteOne({ userId }, { session });\n    });\n  } finally { session.endSession(); }\n}', difficulty: "intermediate" }], externalLinks: [{ title: "MongoDB Transactions", url: "https://www.mongodb.com/docs/manual/core/transactions/" }], estimatedMinutes: 30 },
    { id: "mongo-11", title: "Data Modeling Patterns", content: "MongoDB data modeling differs fundamentally from relational design. Advanced patterns include the bucket pattern for time-series data, the polymorphic pattern for varied document shapes, the computed pattern for pre-calculated values, the outlier pattern for handling large documents, and schema versioning for evolving data structures.", codeExamples: [{ language: "javascript", code: '// Bucket pattern (time-series)\nconst sensorReading = {\n  sensorId: "temp-001",\n  date: new Date("2024-01-15"),\n  readings: [\n    { time: "08:00", value: 22.5 },\n    { time: "09:00", value: 23.1 },\n    { time: "10:00", value: 24.0 }\n  ],\n  count: 3, sum: 69.6, avg: 23.2\n};\n// Groups readings by day — fewer documents, faster queries\n\n// Polymorphic pattern\nconst notifications = [\n  { type: "email", to: "ali@test.com", subject: "Welcome" },\n  { type: "sms", phone: "+923001234567", message: "Code: 1234" },\n  { type: "push", deviceId: "abc", title: "New message" }\n];\n// Same collection, different shapes — query by type', explanation: "Bucket and polymorphic patterns." }, { language: "javascript", code: '// Computed pattern — pre-calculate on write\nconst productSchema = {\n  name: "Laptop",\n  reviews: [/* stored separately */],\n  // Pre-computed on each review write\n  computed: {\n    reviewCount: 450,\n    avgRating: 4.3,\n    ratingDistribution: { 5: 200, 4: 150, 3: 60, 2: 25, 1: 15 }\n  }\n};\n// Reads are instant — no aggregation needed at query time\n// Update computed fields when new review is added:\nawait products.updateOne({ _id: productId }, {\n  $inc: {\n    "computed.reviewCount": 1,\n    [`computed.ratingDistribution.${rating}`]: 1\n  }\n});', explanation: "Computed pattern for read-heavy workloads." }, { language: "javascript", code: '// Schema versioning\nconst userV1 = { name: "Ali", address: "Karachi" };\nconst userV2 = {\n  name: "Ali",\n  address: { city: "Karachi", country: "PK" },\n  schemaVersion: 2\n};\n\n// Lazy migration on read\nfunction normalizeUser(doc) {\n  if (!doc.schemaVersion || doc.schemaVersion < 2) {\n    return {\n      ...doc,\n      address: typeof doc.address === "string"\n        ? { city: doc.address, country: "PK" }\n        : doc.address,\n      schemaVersion: 2\n    };\n  }\n  return doc;\n}', explanation: "Schema versioning for evolving data." }], exercises: [{ question: "Design schemas for an e-commerce app using embedding, referencing, and computed patterns.", solution: '// Product: embed category, compute review stats\nconst product = {\n  name: "Laptop", price: 999,\n  category: { id: "electronics", name: "Electronics" },\n  computed: { avgRating: 4.5, reviewCount: 120 }\n};\n// Order: embed product snapshots (denormalize)\nconst order = {\n  userId: ObjectId(), items: [\n    { productId: ObjectId(), name: "Laptop", priceAtPurchase: 999, qty: 1 }\n  ], total: 999\n};\n// Review: reference product and user\nconst review = { productId: ObjectId(), userId: ObjectId(), rating: 5 };', difficulty: "intermediate" }], externalLinks: [{ title: "MongoDB Patterns", url: "https://www.mongodb.com/blog/post/building-with-patterns-a-summary" }], estimatedMinutes: 30 },
    { id: "mongo-12", title: "Mongoose Population & Virtuals", content: "Mongoose populate simulates SQL JOINs by replacing ObjectId references with actual documents. Virtual populate creates relationships without storing IDs in the parent. Discriminators enable single-collection inheritance. Lean queries return plain objects for better performance. These features make Mongoose powerful for complex data relationships.", codeExamples: [{ language: "javascript", code: '// Basic and nested populate\nconst postSchema = new mongoose.Schema({\n  title: String,\n  author: { type: mongoose.Schema.Types.ObjectId, ref: "User" },\n  comments: [{\n    text: String,\n    user: { type: mongoose.Schema.Types.ObjectId, ref: "User" }\n  }]\n});\n\n// Populate author\nconst post = await Post.findById(id).populate("author", "name email avatar");\n\n// Deep populate comments.user\nconst postWithComments = await Post.findById(id)\n  .populate("author", "name")\n  .populate("comments.user", "name avatar");\n\n// Conditional populate\nconst posts = await Post.find()\n  .populate({\n    path: "author",\n    match: { isActive: true },\n    select: "name email"\n  });', explanation: "Basic, nested, and conditional population." }, { language: "javascript", code: '// Virtual populate — no foreign keys stored in parent\nconst authorSchema = new mongoose.Schema({\n  name: String,\n  email: String\n}, { toJSON: { virtuals: true } });\n\n// Virtual field: get all posts by this author\nauthorSchema.virtual("posts", {\n  ref: "Post",\n  localField: "_id",\n  foreignField: "author"\n});\n\nconst author = await Author.findById(id).populate("posts");\nconsole.log(author.posts); // All posts by this author\n\n// Virtual with count\nauthorSchema.virtual("postCount", {\n  ref: "Post",\n  localField: "_id",\n  foreignField: "author",\n  count: true\n});\nconst authorWithCount = await Author.findById(id).populate("postCount");\nconsole.log(authorWithCount.postCount); // 15', explanation: "Virtual populate for reverse relationships." }, { language: "javascript", code: '// Discriminators — single-collection inheritance\nconst eventSchema = new mongoose.Schema({\n  date: Date,\n  location: String\n}, { discriminatorKey: "type" });\n\nconst Event = mongoose.model("Event", eventSchema);\n\nconst ClickEvent = Event.discriminator("Click", new mongoose.Schema({\n  element: String,\n  url: String\n}));\n\nconst PurchaseEvent = Event.discriminator("Purchase", new mongoose.Schema({\n  product: String,\n  amount: Number\n}));\n\n// All stored in same collection with a "type" field\nawait ClickEvent.create({ date: new Date(), element: "button", url: "/buy" });\nawait PurchaseEvent.create({ date: new Date(), product: "Laptop", amount: 999 });\n\n// Query all events or by type\nconst allEvents = await Event.find();\nconst purchases = await PurchaseEvent.find();', explanation: "Discriminators for polymorphic collections." }], exercises: [{ question: "Create a virtual populate that retrieves all orders for a user without storing order IDs on the user document.", solution: 'const userSchema = new mongoose.Schema({\n  name: String, email: String\n}, { toJSON: { virtuals: true } });\n\nuserSchema.virtual("orders", {\n  ref: "Order", localField: "_id", foreignField: "userId"\n});\nuserSchema.virtual("orderCount", {\n  ref: "Order", localField: "_id", foreignField: "userId", count: true\n});\n\nconst user = await User.findById(id)\n  .populate("orders")\n  .populate("orderCount");', difficulty: "intermediate" }], externalLinks: [{ title: "Mongoose Populate", url: "https://mongoosejs.com/docs/populate.html" }], estimatedMinutes: 30 },
  ],
  hard: [
    { id: "mongo-13", title: "Change Streams & Real-Time", content: "Change streams let applications watch for real-time data changes in MongoDB collections. They use the oplog to track inserts, updates, deletes, and replacements. Combined with WebSockets, change streams enable live dashboards, notifications, and collaborative features. Resume tokens allow reconnecting without missing events.", codeExamples: [{ language: "javascript", code: '// Basic change stream\nconst collection = db.collection("messages");\nconst changeStream = collection.watch();\n\nchangeStream.on("change", (change) => {\n  console.log("Operation:", change.operationType);\n  console.log("Document:", change.fullDocument);\n  console.log("Resume token:", change._id);\n  \n  switch (change.operationType) {\n    case "insert":\n      io.emit("newMessage", change.fullDocument);\n      break;\n    case "update":\n      io.emit("messageUpdated", {\n        id: change.documentKey._id,\n        changes: change.updateDescription.updatedFields\n      });\n      break;\n    case "delete":\n      io.emit("messageDeleted", change.documentKey._id);\n      break;\n  }\n});', explanation: "Change stream with event-type handling." }, { language: "javascript", code: '// Filtered change stream with pipeline\nconst pipeline = [\n  { $match: {\n    "fullDocument.priority": "high",\n    operationType: { $in: ["insert", "update"] }\n  }}\n];\n\nconst stream = collection.watch(pipeline, {\n  fullDocument: "updateLookup" // include full doc on updates\n});\n\n// Resume after disconnect\nlet resumeToken = loadSavedToken();\nconst stream = collection.watch([], {\n  resumeAfter: resumeToken\n});\nstream.on("change", (change) => {\n  saveToken(change._id); // persist for recovery\n  processChange(change);\n});', explanation: "Filtered streams and resume tokens." }, { language: "javascript", code: '// Real-time dashboard with Express + Socket.IO\nconst http = require("http");\nconst { Server } = require("socket.io");\n\nconst server = http.createServer(app);\nconst io = new Server(server, { cors: { origin: "*" } });\n\n// Watch orders collection\nconst orderStream = db.collection("orders").watch();\norderStream.on("change", async (change) => {\n  if (change.operationType === "insert") {\n    const stats = await db.collection("orders").aggregate([\n      { $group: { _id: null, total: { $sum: "$amount" }, count: { $sum: 1 } } }\n    ]).toArray();\n    io.emit("dashboardUpdate", stats[0]);\n  }\n});', explanation: "Real-time dashboard with change streams and WebSocket." }], exercises: [{ question: "Build a real-time notification system using change streams that watches for new orders.", solution: 'const orderStream = db.collection("orders").watch(\n  [{ $match: { operationType: "insert" } }],\n  { fullDocument: "updateLookup" }\n);\norderStream.on("change", (change) => {\n  const order = change.fullDocument;\n  io.to(`user:${order.userId}`).emit("notification", {\n    type: "order_placed",\n    message: `Order #${order._id} placed for $${order.total}`\n  });\n});', difficulty: "advanced" }], externalLinks: [{ title: "Change Streams", url: "https://www.mongodb.com/docs/manual/changeStreams/" }], estimatedMinutes: 30 },
    { id: "mongo-14", title: "Geospatial Queries", content: "MongoDB supports geospatial data with 2dsphere indexes for Earth-like geometry and 2d indexes for flat surfaces. GeoJSON objects (Point, LineString, Polygon) represent locations. Operators like $near, $geoWithin, and $geoIntersects enable location-based queries — finding nearby restaurants, stores within a delivery zone, or routes crossing an area.", codeExamples: [{ language: "javascript", code: '// Store location data as GeoJSON\nconst storeSchema = new mongoose.Schema({\n  name: String,\n  location: {\n    type: { type: String, enum: ["Point"], required: true },\n    coordinates: { type: [Number], required: true } // [longitude, latitude]\n  },\n  address: String,\n  category: String\n});\n\n// Create 2dsphere index\nstoreSchema.index({ location: "2dsphere" });\n\n// Insert stores\nawait Store.create({\n  name: "Coffee House",\n  location: { type: "Point", coordinates: [67.0011, 24.8607] }, // Karachi\n  category: "cafe"\n});', explanation: "GeoJSON data storage with 2dsphere index." }, { language: "javascript", code: '// Find stores near a point\nconst nearbyStores = await Store.find({\n  location: {\n    $near: {\n      $geometry: { type: "Point", coordinates: [67.0011, 24.8607] },\n      $maxDistance: 5000 // 5km radius in meters\n    }\n  }\n});\n\n// Find stores within a polygon (delivery zone)\nconst inZone = await Store.find({\n  location: {\n    $geoWithin: {\n      $geometry: {\n        type: "Polygon",\n        coordinates: [[\n          [66.99, 24.85], [67.01, 24.85],\n          [67.01, 24.87], [66.99, 24.87],\n          [66.99, 24.85] // close the polygon\n        ]]\n      }\n    }\n  }\n});', explanation: "$near and $geoWithin queries." }, { language: "javascript", code: '// Aggregation with $geoNear (must be first stage)\nconst nearWithDistance = await Store.aggregate([\n  {\n    $geoNear: {\n      near: { type: "Point", coordinates: [67.0011, 24.8607] },\n      distanceField: "distance", // adds distance in meters\n      maxDistance: 10000,\n      spherical: true,\n      query: { category: "cafe" } // additional filter\n    }\n  },\n  { $project: { name: 1, distance: { $round: ["$distance", 0] } } },\n  { $sort: { distance: 1 } },\n  { $limit: 10 }\n]);\n// Returns: [{ name: "Coffee House", distance: 450 }, ...]', explanation: "$geoNear aggregation with distance calculation." }], exercises: [{ question: "Build a store locator that finds the 5 nearest stores to a user's location within 10km.", solution: 'async function findNearby(lng, lat, maxKm = 10) {\n  return Store.aggregate([\n    { $geoNear: {\n      near: { type: "Point", coordinates: [lng, lat] },\n      distanceField: "distance",\n      maxDistance: maxKm * 1000,\n      spherical: true\n    }},\n    { $limit: 5 },\n    { $project: { name: 1, address: 1, distance: { $round: [{ $divide: ["$distance", 1000] }, 1] } } }\n  ]);\n}', difficulty: "advanced" }], externalLinks: [{ title: "Geospatial Queries", url: "https://www.mongodb.com/docs/manual/geospatial-queries/" }], estimatedMinutes: 30 },
    { id: "mongo-15", title: "Sharding & Horizontal Scaling", content: "Sharding distributes data across multiple servers for horizontal scaling. MongoDB automatically balances data across shards. A shard key determines how documents are distributed. Choosing the right shard key is critical — it affects query performance, data distribution, and scalability. Common shard key strategies include hashed keys for even distribution and ranged keys for locality.", codeExamples: [{ language: "javascript", code: '// Shard key selection considerations\n// Good shard keys have:\n// 1. High cardinality (many unique values)\n// 2. Low frequency (values are evenly distributed)\n// 3. Non-monotonic (don\'t always increase)\n\n// GOOD: hashed _id — even distribution\nsh.shardCollection("mydb.orders", { _id: "hashed" });\n\n// GOOD: compound key — query isolation + distribution\nsh.shardCollection("mydb.orders", { customerId: 1, orderDate: 1 });\n\n// BAD: monotonically increasing — creates hotspot\n// sh.shardCollection("mydb.logs", { timestamp: 1 }); // Don\'t!\n\n// BAD: low cardinality\n// sh.shardCollection("mydb.users", { country: 1 }); // Only ~200 values', explanation: "Shard key selection strategies." }, { language: "javascript", code: '// Sharded cluster architecture\n// Config servers: store metadata and chunk mappings\n// Mongos: query router — clients connect here\n// Shards: store the actual data (each is a replica set)\n\n// Check shard distribution\ndb.orders.getShardDistribution();\n// Output shows how data is spread across shards\n\n// Targeted vs scatter-gather queries\n// Targeted (fast): query includes shard key\ndb.orders.find({ customerId: "C123" }); // goes to ONE shard\n\n// Scatter-gather (slow): query doesn\'t include shard key\ndb.orders.find({ status: "pending" }); // hits ALL shards', explanation: "Sharded cluster architecture and query routing." }, { language: "javascript", code: '// Monitoring sharded cluster\ndb.printShardingStatus(); // overall status\ndb.adminCommand({ balancerStatus: 1 }); // balancer info\n\n// Zone-based sharding (data locality)\n// Keep EU data on EU servers\nsh.addShardTag("shard-eu", "EU");\nsh.addShardTag("shard-us", "US");\n\nsh.addTagRange("mydb.users",\n  { region: "EU" }, { region: "EU~" }, "EU"\n);\nsh.addTagRange("mydb.users",\n  { region: "US" }, { region: "US~" }, "US"\n);\n// EU users automatically stored on EU shard', explanation: "Zone-based sharding for data locality." }], exercises: [{ question: "Design a sharding strategy for a multi-tenant SaaS application.", solution: '// Shard key: { tenantId: 1, _id: 1 }\n// Why: tenant queries are targeted to one shard\n// _id provides uniqueness within tenant\nsh.shardCollection("saas.documents", { tenantId: 1, _id: 1 });\n\n// Large tenants get their own zones\nsh.addShardTag("shard-premium", "PREMIUM");\nsh.addTagRange("saas.documents",\n  { tenantId: "big-corp" }, { tenantId: "big-corp~" }, "PREMIUM"\n);', difficulty: "advanced" }], externalLinks: [{ title: "MongoDB Sharding", url: "https://www.mongodb.com/docs/manual/sharding/" }], estimatedMinutes: 35 },
    { id: "mongo-16", title: "Security & Production", content: "Securing MongoDB in production involves authentication, authorization, encryption, and network security. Enable authentication with SCRAM-SHA-256, use role-based access control, encrypt data at rest and in transit with TLS. Proper backup strategies, monitoring, and connection pooling ensure reliability and data safety.", codeExamples: [{ language: "javascript", code: '// Secure connection with TLS and auth\nconst client = new MongoClient(process.env.MONGODB_URI, {\n  tls: true,\n  tlsCAFile: "/path/to/ca.pem",\n  auth: { username: process.env.DB_USER, password: process.env.DB_PASS },\n  maxPoolSize: 50,\n  minPoolSize: 5,\n  maxIdleTimeMS: 30000,\n  serverSelectionTimeoutMS: 5000\n});\n\n// Input sanitization to prevent injection\nconst sanitize = require("mongo-sanitize");\napp.post("/api/login", (req, res) => {\n  const cleanBody = sanitize(req.body);\n  // Prevents { "$gt": "" } injection\n  User.findOne({ email: cleanBody.email });\n});\n\n// Schema validation at database level\ndb.createCollection("users", {\n  validator: {\n    $jsonSchema: {\n      bsonType: "object",\n      required: ["name", "email"],\n      properties: { email: { bsonType: "string", pattern: "^.+@.+\\\\..+$" } }\n    }\n  }\n});', explanation: "Secure connections and injection prevention." }, { language: "javascript", code: '// Connection management with retry\nlet cachedDb = null;\n\nasync function getDb() {\n  if (cachedDb) return cachedDb;\n  const client = await MongoClient.connect(process.env.MONGODB_URI, {\n    maxPoolSize: 10\n  });\n  cachedDb = client.db("myapp");\n  client.on("error", (err) => {\n    console.error("MongoDB error:", err);\n    cachedDb = null;\n  });\n  return cachedDb;\n}\n\n// Graceful shutdown\nprocess.on("SIGINT", async () => {\n  await client.close();\n  process.exit(0);\n});', explanation: "Connection pooling and graceful shutdown." }, { language: "javascript", code: '// Backup and monitoring\n// mongodump — full backup\n// mongodump --uri="mongodb://..." --out=/backup/$(date +%Y%m%d)\n\n// mongorestore — restore from backup\n// mongorestore --uri="mongodb://..." /backup/20240115\n\n// Monitoring commands\ndb.serverStatus();          // server metrics\ndb.currentOp();             // running operations\ndb.stats();                 // database statistics\ndb.collection.stats();      // collection statistics\n\n// Profiler for slow queries\ndb.setProfilingLevel(1, { slowms: 100 }); // log queries > 100ms\ndb.system.profile.find().sort({ ts: -1 }).limit(10);', explanation: "Backup, restore, and monitoring." }], exercises: [{ question: "Set up a MongoDB connection with error handling, connection pooling, and automatic reconnection.", solution: 'async function connectWithRetry(uri, retries = 5) {\n  for (let i = 0; i < retries; i++) {\n    try {\n      const client = await MongoClient.connect(uri, {\n        maxPoolSize: 20, serverSelectionTimeoutMS: 5000\n      });\n      client.on("error", console.error);\n      return client;\n    } catch (e) {\n      console.log(`Retry ${i + 1}/${retries}...`);\n      await new Promise(r => setTimeout(r, 2000 * (i + 1)));\n    }\n  }\n  throw new Error("Failed to connect");\n}', difficulty: "advanced" }], externalLinks: [{ title: "MongoDB Security Checklist", url: "https://www.mongodb.com/docs/manual/administration/security-checklist/" }], estimatedMinutes: 30 },
    { id: "mongo-17", title: "Atlas Search & Full-Text", content: "MongoDB Atlas Search powered by Apache Lucene provides advanced full-text search capabilities including fuzzy matching, autocomplete, faceted search, and relevance scoring. It integrates directly into the aggregation pipeline via $search, eliminating the need for a separate search engine like Elasticsearch for many use cases.", codeExamples: [{ language: "javascript", code: '// Atlas Search with $search stage\nconst results = await products.aggregate([\n  { $search: {\n    index: "product_search",\n    text: {\n      query: "gaming laptop",\n      path: ["name", "description"],\n      fuzzy: { maxEdits: 1 } // typo tolerance\n    }\n  }},\n  { $project: {\n    name: 1, price: 1,\n    score: { $meta: "searchScore" }\n  }},\n  { $limit: 20 }\n]).toArray();\n\n// Autocomplete\nconst suggestions = await products.aggregate([\n  { $search: {\n    index: "autocomplete_index",\n    autocomplete: { query: "lap", path: "name" }\n  }},\n  { $project: { name: 1 } },\n  { $limit: 5 }\n]).toArray();', explanation: "Full-text search with fuzzy matching and autocomplete." }, { language: "javascript", code: '// Compound search with boosting\nconst search = await products.aggregate([\n  { $search: {\n    compound: {\n      must: [{ text: { query: "laptop", path: "name" } }],\n      should: [\n        { text: { query: "gaming", path: "description", score: { boost: { value: 2 } } } }\n      ],\n      filter: [\n        { range: { path: "price", gte: 500, lte: 2000 } }\n      ]\n    }\n  }},\n  { $limit: 10 }\n]).toArray();', explanation: "Compound search with filtering and boosting." }, { language: "javascript", code: '// Faceted search for e-commerce filters\nconst facetResults = await products.aggregate([\n  { $searchMeta: {\n    index: "product_search",\n    facet: {\n      operator: { text: { query: "laptop", path: "name" } },\n      facets: {\n        categoryFacet: { type: "string", path: "category" },\n        priceFacet: {\n          type: "number", path: "price",\n          boundaries: [0, 500, 1000, 2000, 5000]\n        }\n      }\n    }\n  }}\n]).toArray();\n// Returns counts per category and price range', explanation: "Faceted search for filter panels." }], exercises: [{ question: "Build a product search with fuzzy matching, category filters, and relevance scoring.", solution: 'async function searchProducts(query, category, page = 1) {\n  const pipeline = [{ $search: {\n    compound: {\n      must: [{ text: { query, path: ["name", "description"], fuzzy: { maxEdits: 1 } } }],\n      filter: category ? [{ text: { query: category, path: "category" } }] : []\n    }\n  }}];\n  pipeline.push({ $project: { name: 1, price: 1, score: { $meta: "searchScore" } } });\n  pipeline.push({ $skip: (page - 1) * 20 }, { $limit: 20 });\n  return products.aggregate(pipeline).toArray();\n}', difficulty: "advanced" }], externalLinks: [{ title: "Atlas Search", url: "https://www.mongodb.com/docs/atlas/atlas-search/" }], estimatedMinutes: 30 },
    { id: "mongo-18", title: "Performance Tuning & Optimization", content: "MongoDB performance tuning involves profiling slow queries, optimizing indexes, tuning connection pools, using read preferences for replica sets, configuring write concerns, and monitoring with tools like mongostat and mongotop. Understanding the query planner, covered queries, and the working set concept is essential for production performance.", codeExamples: [{ language: "javascript", code: '// Profiler for finding slow queries\ndb.setProfilingLevel(1, { slowms: 50 }); // log queries > 50ms\n\n// Analyze slow queries\ndb.system.profile.find({\n  millis: { $gt: 100 }\n}).sort({ ts: -1 }).limit(5).forEach(op => {\n  console.log({\n    operation: op.op,\n    namespace: op.ns,\n    query: op.command?.filter || op.command,\n    executionTime: op.millis + "ms",\n    docsExamined: op.docsExamined,\n    keysExamined: op.keysExamined\n  });\n});\n\n// Key metric: docsExamined / nReturned ratio\n// Ideal: close to 1 (index fully covers the query)\n// Bad: >> 1 (scanning many docs to return few)', explanation: "Query profiling and performance metrics." }, { language: "javascript", code: '// Read preferences for replica sets\nconst readPref = require("mongodb").ReadPreference;\n\n// Analytics queries on secondary (reduce primary load)\nconst analytics = db.collection("events").find(\n  { type: "pageview" },\n  { readPreference: readPref.SECONDARY_PREFERRED }\n);\n\n// Write concerns for different use cases\n// Fast writes (fire-and-forget for logs)\nawait logs.insertOne(data, { writeConcern: { w: 0 } });\n\n// Durable writes (financial data)\nawait transactions.insertOne(data, {\n  writeConcern: { w: "majority", j: true, wtimeout: 5000 }\n});', explanation: "Read preferences and write concerns." }, { language: "javascript", code: '// Mongoose performance optimizations\n\n// Lean queries — 5x faster for read-only\nconst users = await User.find({ active: true }).lean();\n// Returns plain objects (no Mongoose methods)\n\n// Select only needed fields\nconst names = await User.find().select("name email -_id").lean();\n\n// Cursor-based iteration for large datasets\nconst cursor = User.find().lean().cursor();\nfor await (const user of cursor) {\n  await processUser(user); // process one at a time, low memory\n}\n\n// Batch operations instead of loops\n// BAD:\nfor (const id of ids) await User.updateOne({ _id: id }, { active: false });\n// GOOD:\nawait User.updateMany({ _id: { $in: ids } }, { active: false });', explanation: "Mongoose performance patterns." }], exercises: [{ question: "Profile and optimize a slow MongoDB query by adding indexes and restructuring the query.", solution: '// Original slow query\n// db.orders.find({ status: "pending", userId: "u1" }).sort({ createdAt: -1 })\n\n// Step 1: Check explain\nconst plan = await db.collection("orders")\n  .find({ status: "pending", userId: "u1" })\n  .sort({ createdAt: -1 }).explain("executionStats");\n// Shows COLLSCAN — no index!\n\n// Step 2: Add compound index\nawait db.collection("orders").createIndex({ userId: 1, status: 1, createdAt: -1 });\n\n// Step 3: Verify — now uses IXSCAN\n// docsExamined matches nReturned', difficulty: "advanced" }], externalLinks: [{ title: "MongoDB Performance", url: "https://www.mongodb.com/docs/manual/administration/analyzing-mongodb-performance/" }], estimatedMinutes: 35 },
  ],
};
